# ======================================================================= events
E = [
 ("dust_devil","Dust devil","พายุหมุนฝุ่น",
  "A dust devil is crossing the plain tonight. Stow the solar panels before bed.","คืนนี้มีพายุหมุนฝุ่นพัดผ่าน เก็บแผงโซลาร์ก่อนนอน",
  "The dust devil buried the open panels in dust. Less power tomorrow.","พายุหมุนฝุ่นพัดฝุ่นใส่แผงที่กางอยู่ พรุ่งนี้ได้ไฟน้อยลง",
  "The dust devil passed. The stowed panels stayed clean!","พายุหมุนฝุ่นผ่านไปแล้ว แผงที่เก็บไว้ยังสะอาด!",
  "stow the solar panels (outside)","เก็บแผงโซลาร์ (ข้างนอก)"),
 ("micro_leak","Seal fatigue","ซีลเสื่อม",
  "Cold nights stress the seals. A slow leak is likely tonight. Inspect the seals (Life Support panel).","คืนที่หนาวจัดทำให้ซีลเสื่อม คืนนี้อาจรั่วช้าๆ ไปตรวจซีลที่แผงห้องระบบยังชีพ",
  "A tiny leak hissed all night. You lost some oxygen.","รอยรั่วเล็กๆ รั่วทั้งคืน ออกซิเจนหายไปส่วนหนึ่ง",
  "The seals you checked held tight all night.","ซีลที่ตรวจไว้แน่นหนาตลอดคืน",
  "inspect the seals (Life Support)","ตรวจซีล (ห้องระบบยังชีพ)"),
 ("solar_flare","Solar flare","พายุสุริยะ",
  "The Sun is flaring. Radiation arrives tonight. Water is a great shield: keep at least 35 water.","ดวงอาทิตย์ปะทุ รังสีจะมาถึงคืนนี้ น้ำเป็นเกราะกันรังสีที่ดี เก็บน้ำไว้อย่างน้อย 35",
  "Radiation got through the half-empty water wall. You wake up sick and tired.","รังสีทะลุผนังน้ำที่มีน้ำไม่เต็ม คุณตื่นมาป่วยและเหนื่อยล้า",
  "The water wall around your bunk blocked the radiation. Safe!","ผนังน้ำรอบเตียงกันรังสีไว้ได้ ปลอดภัย!",
  "keep 35+ water at bedtime","มีน้ำ 35 ขึ้นไปตอนเข้านอน"),
 ("global_storm","GREAT DUST STORM","พายุฝุ่นครั้งใหญ่",
  "The great dust storm hits tonight! Stow the panels AND have at least 40 power at bedtime.","พายุฝุ่นครั้งใหญ่มาคืนนี้! ต้องเก็บแผงโซลาร์ และมีไฟฟ้าอย่างน้อย 40 ตอนเข้านอน",
  "The storm wrecked the open panels and drained the batteries.","พายุทำแผงที่กางอยู่พังและดูดไฟจากแบตเตอรี่",
  "The storm roared all night, but you were ready.","พายุโหมทั้งคืน แต่คุณเตรียมพร้อมแล้ว",
  "stow panels + 40 power at bedtime","เก็บแผง + ไฟฟ้า 40 ตอนเข้านอน"),
 ("micrometeoroids","Micrometeoroid shower","ฝนอุกกาบาตจิ๋ว",
  "With no air to burn them up, tiny space rocks hit the Moon at full speed. A shower is coming tonight: close the window shutters (Life Support panel).","ดวงจันทร์ไม่มีอากาศเผาหินเล็กๆ ให้ไหม้ หินอวกาศจึงพุ่งชนเต็มความเร็ว คืนนี้มีฝนอุกกาบาตจิ๋ว ปิดบานเกล็ดหน้าต่าง",
  "Tiny rocks cracked a window seal. Oxygen leaked out.","หินจิ๋วทำซีลหน้าต่างร้าว ออกซิเจนรั่วออกไป",
  "Pings on the shutters all night, but nothing got through.","มีเสียงกระทบบานเกล็ดทั้งคืน แต่ไม่มีอะไรทะลุเข้ามา",
  "close the shutters (Life Support panel)","ปิดบานเกล็ด (แผงห้องระบบยังชีพ)"),
 ("moon_dust","Clinging moon dust","ฝุ่นดวงจันทร์เกาะ",
  "Moon dust from your boots is grinding into the seals. Inspect the seals before bed.","ฝุ่นดวงจันทร์จากรองเท้ากำลังกัดซีล ตรวจซีลก่อนนอน",
  "Sharp dust wore a seal through. Oxygen and water leaked.","ฝุ่นคมๆ กัดซีลจนทะลุ ออกซิเจนและน้ำรั่วออกไป",
  "Clean seals held all night.","ซีลที่สะอาดแน่นหนาตลอดคืน",
  "inspect the seals (Life Support)","ตรวจซีล (ห้องระบบยังชีพ)"),
 ("lunar_night","THE LONG SHADOW","เงามืดยาวนาน",
  "The crater's shadow sweeps over us tonight: hours of deep cold and no sun. Set the heaters AND keep at least 40 power at bedtime.","เงาของหลุมจะกวาดผ่านเราคืนนี้: หนาวจัดหลายชั่วโมงและไม่มีแดด ต้องตั้งเครื่องทำความร้อน และมีไฟฟ้าอย่างน้อย 40 ตอนเข้านอน",
  "The cold drained the batteries and chilled you to the bone.","ความหนาวดูดแบตเตอรี่และทำให้คุณหนาวสะท้าน",
  "The heaters kept the cabin warm through the long shadow.","เครื่องทำความร้อนทำให้ห้องอุ่นตลอดเงามืด",
  "set heaters + 40 power at bedtime","ตั้งเครื่องทำความร้อน + ไฟฟ้า 40 ตอนเข้านอน"),
 ("methane_rain","Methane rain","ฝนมีเทน",
  "Methane rain tonight. It seeps into any loose seal. Inspect the seals before bed.","คืนนี้ฝนมีเทนตก มันจะซึมเข้าซีลที่หลวม ตรวจซีลก่อนนอน",
  "Methane seeped in and the scrubbers burned oxygen to clean it.","มีเทนซึมเข้ามา เครื่องกรองต้องใช้ออกซิเจนกำจัด",
  "Rain drummed on the hull, but the seals held.","ฝนตกกระหน่ำบนตัวยาน แต่ซีลแน่นหนา",
  "inspect the seals (Life Support)","ตรวจซีล (ห้องระบบยังชีพ)"),
 ("cold_snap","Cold snap","ความหนาวกระชาก",
  "An extra-cold night. The heaters will need power: keep at least 35 power at bedtime.","คืนที่หนาวเป็นพิเศษ เครื่องทำความร้อนต้องใช้ไฟ มีไฟฟ้าอย่างน้อย 35 ตอนเข้านอน",
  "Not enough power for the heaters. You shivered all night.","ไฟไม่พอให้เครื่องทำความร้อน คุณหนาวสั่นทั้งคืน",
  "The heaters ran all night. Warm and rested.","เครื่องทำความร้อนทำงานทั้งคืน อุ่นและได้พัก",
  "keep 35+ power at bedtime","มีไฟฟ้า 35 ขึ้นไปตอนเข้านอน"),
 ("static_storm","Static storm","พายุไฟฟ้าสถิต",
  "Charged haze is drifting in. Loose RTG cables could short out. Check the RTG outside.","หมอกที่มีประจุกำลังลอยเข้ามา สาย RTG ที่หลวมอาจลัดวงจร ไปตรวจ RTG ข้างนอก",
  "A loose cable sparked. We lost power and the RTG is running weak.","สายหลวมเกิดประกายไฟ เราเสียไฟและ RTG ทำงานได้ไม่เต็มที่",
  "Tight cables, no sparks. The RTG hummed on.","สายแน่น ไม่มีประกายไฟ RTG ทำงานต่อไป",
  "check the RTG (outside)","ตรวจ RTG (ข้างนอก)"),
 ("deep_cold","SATURN'S SHADOW","เงาของดาวเสาร์",
  "Tonight Titan passes into Saturn's shadow: the coldest night of all. Seal the insulation AND keep at least 40 power at bedtime.","คืนนี้ไททันเข้าสู่เงาของดาวเสาร์: คืนที่หนาวที่สุด ต้องปิดฉนวนกันความร้อน และมีไฟฟ้าอย่างน้อย 40 ตอนเข้านอน",
  "The cold broke through. Power, energy and oxygen all suffered.","ความหนาวทะลุเข้ามา ไฟฟ้า พลังกาย และออกซิเจนลดลงหมด",
  "Insulated and powered, the cabin stayed warm in Saturn's shadow.","มีฉนวนและไฟพอ ห้องยังอุ่นในเงาของดาวเสาร์",
  "seal insulation + 40 power at bedtime","ปิดฉนวน + ไฟฟ้า 40 ตอนเข้านอน"),
]
for eid, ne, nt, fe, ft, he, ht, se, st, pe, pt in E:
    k(f"event.{eid}.name", ne, nt); k(f"event.{eid}.forecast", fe, ft); k(f"event.{eid}.hit", he, ht)
    k(f"event.{eid}.saved", se, st); k(f"event.{eid}.prevent", pe, pt)

# ======================================================================= daytime emergencies
I = [
 ("recycler_fire","FIRE in the water recycler! Reach {1} in {0}s!","ไฟไหม้เครื่องรีไซเคิลน้ำ! ไปที่{1}ภายใน {0} วินาที!",
  "Fire out. The recycler is scorched but working.","ดับไฟแล้ว เครื่องรีไซเคิลไหม้นิดหน่อยแต่ยังใช้ได้",
  "The fire burned through the recycler's water and wiring.","ไฟไหม้น้ำและสายไฟของเครื่องรีไซเคิล"),
 ("hatch_leak","AIRLOCK SEAL FAILING! Reach {1} in {0}s!","ซีลประตูปรับแรงดันกำลังพัง! ไปที่{1}ภายใน {0} วินาที!",
  "Airlock resealed. Close one.","ปิดซีลประตูใหม่แล้ว หวุดหวิด",
  "Air whistled out of the airlock before it sealed itself.","อากาศรั่วออกทางประตูก่อนมันจะปิดเอง"),
 ("scrubber_clog","OXYGEN GENERATOR CLOGGED! Reach {1} in {0}s!","เครื่องผลิตออกซิเจนอุดตัน! ไปที่{1}ภายใน {0} วินาที!",
  "Filter cleared. Oxygen flowing again.","ล้างตัวกรองแล้ว ออกซิเจนไหลอีกครั้ง",
  "The clogged generator wasted our oxygen.","เครื่องที่อุดตันทำให้ออกซิเจนสูญเปล่า"),
 ("heater_fail","HEATER FAILURE! Reach {1} in {0}s!","เครื่องทำความร้อนเสีย! ไปที่{1}ภายใน {0} วินาที!",
  "Heater rebooted. Warmth returns.","รีบูตเครื่องทำความร้อนแล้ว ความอุ่นกลับมา",
  "The cabin froze for an hour. You're exhausted.","ห้องเย็นจัดไปหนึ่งชั่วโมง คุณหมดแรง"),
 ("methane_vent","METHANE LEAK in the fuel processor! Reach {1} in {0}s!","มีเทนรั่วที่เครื่องแปรรูปเชื้อเพลิง! ไปที่{1}ภายใน {0} วินาที!",
  "Valve closed. Air is clean.","ปิดวาล์วแล้ว อากาศสะอาด",
  "The scrubbers burned oxygen to clear the methane.","เครื่องกรองต้องใช้ออกซิเจนกำจัดมีเทน"),
]
